import re
for path in ("/workspace/README.rst", "/workspace/CHANGELOG.rst"):
    lines = open(path).read().split("\n")
    print("==", path)
    for i, l in enumerate(lines):
        if re.fullmatch(r"[=\-~^\"']{3,}", l.strip()) and l.strip():
            prev = lines[i-1] if i else ""
            nxt = lines[i+1] if i+1 < len(lines) else ""
            # overline case
            if prev.strip() == "" and nxt.strip():
                title = nxt
            else:
                title = prev
            if len(l.rstrip()) < len(title.rstrip()):
                print("  SHORT underline line", i+1, repr(title), repr(l))
    # trailing whitespace / tabs
    for i,l in enumerate(lines):
        if l != l.rstrip() or "\t" in l:
            print("  whitespace issue line", i+1, repr(l))
    print("  ends with newline:", open(path).read().endswith("\n"))
EOF
